export const ODEME_HTML = "<!DOCTYPE html>\n<html lang=\"tr\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>PayPanel — Oyuncu Paneli</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#f0f2f5;min-height:100vh}\n\n/* NAV */\n.nav{background:#fff;border-bottom:1px solid #e5e7eb;display:flex;align-items:center;justify-content:space-between;padding:0 2rem;height:56px;position:sticky;top:0;z-index:100}\n.nav-logo{display:flex;align-items:center;gap:10px}\n.nav-logo-icon{width:32px;height:32px;background:#2563eb;border-radius:8px;display:flex;align-items:center;justify-content:center}\n.nav-logo-icon svg{width:18px;height:18px;fill:none;stroke:#fff;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.nav-brand{font-size:15px;font-weight:600;color:#111}\n.nav-tabs{display:flex;align-items:center;gap:2px}\n.nav-tab{padding:6px 16px;font-size:13px;border-radius:8px;cursor:pointer;color:#6b7280;display:flex;align-items:center;gap:6px;transition:all .15s;user-select:none;font-weight:500}\n.nav-tab:hover{background:#f0f4ff;color:#2563eb}\n.nav-tab.active{background:#eff6ff;color:#2563eb}\n.nav-tab svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.nav-right{display:flex;align-items:center;gap:12px}\n.nav-bal-amt{font-size:14px;font-weight:600;color:#111;text-align:right}\n.nav-bal-lbl{font-size:11px;color:#9ca3af;text-align:right}\n.avatar{width:34px;height:34px;border-radius:50%;background:#2563eb;color:#fff;font-size:13px;font-weight:600;display:flex;align-items:center;justify-content:center}\n\n/* PAGES */\n.page{display:none;min-height:calc(100vh - 90px)}\n.page.active{display:block}\n.iframe-mode .page{min-height:auto}\n.iframe-mode .page.active{display:block;min-height:100vh}\n.wrap{padding:2rem;max-width:860px;margin:0 auto}\n.wrap-sm{padding:2rem;max-width:680px;margin:0 auto}\n\n/* HOME */\n.greeting{font-size:20px;font-weight:600;color:#111;margin-bottom:4px}\n.sub{font-size:13px;color:#6b7280;margin-bottom:1.5rem}\n.bal-card{background:#2563eb;border-radius:16px;padding:1.5rem 2rem;margin-bottom:1.25rem;display:flex;align-items:center;gap:16px}\n.bal-icon{width:48px;height:48px;background:rgba(255,255,255,.18);border-radius:12px;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.bal-icon svg{width:24px;height:24px;stroke:#fff;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n.bal-lbl{font-size:13px;color:rgba(255,255,255,.7);margin-bottom:4px}\n.bal-amt{font-size:28px;font-weight:700;color:#fff;letter-spacing:-.5px}\n.home-actions{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:1.5rem}\n.hbtn{border-radius:14px;padding:1.1rem 1.5rem;font-size:15px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;border:none;font-family:inherit;transition:opacity .15s}\n.hbtn:hover{opacity:.88}\n.hbtn svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}\n.hbtn-d{background:#2563eb;color:#fff}\n.hbtn-w{background:#fff;color:#111;border:1px solid #e5e7eb}\n.hbtn-w:hover{border-color:#2563eb;color:#2563eb;opacity:1}\n.txn-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem}\n.txn-title{font-size:15px;font-weight:600;color:#111}\n.txn-list{display:flex;flex-direction:column;gap:8px}\n.txn-card{background:#fff;border-radius:12px;padding:14px 16px;display:flex;align-items:center;justify-content:space-between}\n.txn-l{display:flex;align-items:center;gap:12px}\n.txn-ico{width:36px;height:36px;border-radius:50%;background:#e8f5e9;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.txn-ico svg{width:16px;height:16px;stroke:#1a7c42;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.txn-name{font-size:14px;font-weight:500;color:#111}\n.txn-time{font-size:12px;color:#9ca3af;margin-top:2px}\n.txn-r{display:flex;align-items:center;gap:10px}\n.badge{padding:4px 10px;border-radius:20px;font-size:12px;font-weight:500;display:inline-flex;align-items:center;gap:4px}\n.badge::before{content:'';width:6px;height:6px;border-radius:50%;display:inline-block}\n.b-proc{background:#eff6ff;color:#2563eb}.b-proc::before{background:#2563eb}\n.b-appr{background:#e8f5e9;color:#1a7c42}.b-appr::before{background:#1a7c42}\n.b-pend{background:#fffbeb;color:#d97706}.b-pend::before{background:#d97706}\n.b-rej{background:#fef3f2;color:#dc2626}.b-rej::before{background:#dc2626}\n.txn-amt{font-size:14px;font-weight:600;color:#111}\n\n/* DEPOSIT */\n.page-hd{display:flex;align-items:center;gap:12px;margin-bottom:6px}\n.page-back{width:32px;height:32px;border-radius:50%;background:#fff;border:1px solid #e5e7eb;display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:14px;color:#6b7280;flex-shrink:0}\n.page-back:hover{background:#f3f4f6}\n.page-icon svg{width:24px;height:24px;stroke:#2563eb;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.page-title{font-size:20px;font-weight:600;color:#111}\n.page-sub{font-size:13px;color:#6b7280;margin-bottom:1.5rem;padding-left:44px}\n.card-box{background:#fff;border-radius:14px;border:1px solid #e5e7eb;padding:1.5rem;margin-bottom:1rem}\n.card-box-title{font-size:14px;font-weight:600;color:#111;margin-bottom:1rem}\n.method-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.method-opt{border:1px solid #e5e7eb;border-radius:12px;padding:1.25rem 1rem;display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer;transition:all .15s;background:#fff}\n.method-opt:hover{border-color:#2563eb;background:#f8faff}\n.method-opt.sel{border:2px solid #2563eb;background:#f0f6ff}\n.method-opt svg{width:24px;height:24px;stroke:#6b7280;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n.method-opt.sel svg{stroke:#2563eb}\n.method-opt span{font-size:13px;font-weight:500;color:#374151}\n.method-opt.sel span{color:#2563eb}\n.method-opt.disabled{opacity:.4;cursor:not-allowed;pointer-events:none}\n.method-opt.disabled::after{content:'Yakında';font-size:10px;font-weight:600;color:#9ca3af;text-transform:uppercase;letter-spacing:.04em;margin-top:-4px}\n.amt-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:1rem}\n.amt-opt{border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center;font-size:14px;font-weight:500;color:#374151;cursor:pointer;background:#fff;transition:all .15s}\n.amt-opt:hover{border-color:#2563eb;color:#2563eb}\n.amt-opt.sel{border:2px solid #2563eb;color:#2563eb;background:#eff6ff}\n.amt-custom{display:flex;align-items:center;gap:8px;border:1px solid #e5e7eb;border-radius:10px;padding:10px 14px;background:#f9fafb}\n.amt-custom span{font-size:14px;color:#9ca3af;flex-shrink:0}\n.amt-custom input{border:none;background:transparent;font-size:14px;font-weight:500;color:#111;font-family:inherit;width:100%;outline:none}\n\n/* BANK */\n.bank-grid-ui{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:1rem}\n.bank-opt{display:flex;align-items:center;justify-content:center;padding:20px 16px;background:#fff;border:1px solid #e5e7eb;border-radius:12px;cursor:pointer;transition:all .15s;min-height:76px}\n.bank-opt:hover{border-color:#2563eb;background:#f8faff}\n.bank-opt svg{width:38px;height:38px;flex-shrink:0;border-radius:10px}\n@keyframes dot-bounce{0%,80%,100%{transform:scale(0.6);opacity:.5}40%{transform:scale(1);opacity:1}}\n.bank-opt img{max-width:130px;max-height:48px;object-fit:contain}\n.bok{width:38px;height:38px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;color:#fff;flex-shrink:0}\n.bon{font-size:14px;font-weight:500;color:#111;display:none}\n\n/* FORM SHARED */\n.info-box{display:flex;align-items:flex-start;gap:10px;padding:12px 16px;border-radius:10px;margin-bottom:1.25rem;font-size:13px;line-height:1.6}\n.info-blue{background:#eff6ff;color:#1e40af;border:1px solid #bfdbfe}\n.info-yellow{background:#fffbeb;color:#92400e;border:1px solid #fde68a}\n.info-red{background:#fef3f2;color:#991b1b;border:1px solid #fecaca}\n.info-box svg{width:16px;height:16px;flex-shrink:0;margin-top:2px;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.info-blue svg{stroke:#2563eb}\n.info-yellow svg{stroke:#d97706}\n.info-red svg{stroke:#dc2626}\n.login-card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:1.5rem;margin-bottom:1rem}\n.login-card-hd{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:600;color:#374151;margin-bottom:1.25rem}\n.login-card-hd svg{width:16px;height:16px;stroke:#6b7280;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.fl{margin-bottom:1rem}\n.fl:last-child{margin-bottom:0}\n.fl label{display:block;font-size:13px;color:#374151;margin-bottom:6px;font-weight:500}\n.fl input{width:100%;padding:10px 14px;font-size:14px;border:1px solid #e5e7eb;border-radius:10px;background:#f9fafb;color:#111;font-family:inherit;transition:border-color .15s}\n.fl input:focus{outline:none;border-color:#2563eb;background:#fff;box-shadow:0 0 0 3px rgba(37,99,235,.08)}\n.err-msg{font-size:13px;color:#dc2626;min-height:18px;margin-bottom:.75rem}\n.submit-btn{width:100%;padding:14px;background:#2563eb;color:#fff;border:none;border-radius:12px;font-size:15px;font-weight:600;cursor:pointer;font-family:inherit;transition:opacity .15s;display:flex;align-items:center;justify-content:center;gap:8px}\n.submit-btn:hover{opacity:.88}\n.submit-btn:disabled{opacity:.45;cursor:not-allowed}\n.submit-btn svg{width:16px;height:16px;stroke:#fff;fill:none;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}\n.sms-card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:1.5rem;margin-bottom:1rem}\n.sms-input{width:100%;padding:12px 14px;font-size:24px;font-weight:600;letter-spacing:10px;text-align:center;border:1px solid #e5e7eb;border-radius:10px;background:#f9fafb;color:#111;font-family:inherit;transition:border-color .15s}\n.sms-input:focus{outline:none;border-color:#2563eb;background:#fff;box-shadow:0 0 0 3px rgba(37,99,235,.08)}\n.resend{font-size:12px;color:#9ca3af;text-align:center;margin-bottom:1.25rem}\n.resend span{color:#2563eb;cursor:pointer}\n\n/* ── GİRİŞ YAPILIYOR SAYFASI ── */\n.logging-in-wrap{padding:3rem 2rem;max-width:500px;margin:0 auto;text-align:center}\n.bank-header{display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:2rem}\n.bank-header .bok{width:48px;height:48px;border-radius:14px;font-size:16px}\n.bank-header-name{font-size:20px;font-weight:600;color:#111}\n.login-spinner{width:72px;height:72px;border-radius:50%;background:#eff6ff;display:flex;align-items:center;justify-content:center;margin:0 auto 1.5rem}\n.login-spinner svg{width:32px;height:32px;stroke:#2563eb;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n@keyframes rot{to{transform:rotate(360deg)}}\n.spin-ring-lg{width:40px;height:40px;border:3px solid #bfdbfe;border-top-color:#2563eb;border-radius:50%;animation:rot 1s linear infinite}\n.login-status-title{font-size:18px;font-weight:600;color:#111;margin-bottom:8px}\n.login-status-sub{font-size:14px;color:#6b7280;margin-bottom:2rem;line-height:1.6}\n.login-steps{text-align:left;max-width:260px;margin:0 auto 2rem}\n.lstep{display:flex;align-items:center;gap:12px;padding:7px 0}\n.lstep-ico{width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:12px;font-weight:600;transition:all .3s}\n.lstep-ico.ok{background:#e8f5e9;color:#1a7c42}\n.lstep-ico.spin{background:#eff6ff}\n.lstep-ico.wait{background:#f3f4f6;color:#9ca3af}\n.lstep-ico.err{background:#fef3f2;color:#dc2626}\n.lstep-lbl{font-size:14px;color:#111}\n.lstep-lbl.muted{color:#9ca3af}\n@keyframes spin{to{transform:rotate(360deg)}}\n.spin-ring{width:14px;height:14px;border:2px solid #bfdbfe;border-top-color:#2563eb;border-radius:50%;animation:spin .8s linear infinite}\n\n/* Hata kutusu (giriş yapılıyor sayfasında) */\n.login-error-card{background:#fff;border:1px solid #fecaca;border-radius:14px;padding:1.5rem;text-align:left;margin-bottom:1.5rem}\n.login-error-icon{width:48px;height:48px;border-radius:50%;background:#fef3f2;display:flex;align-items:center;justify-content:center;margin-bottom:1rem}\n.login-error-icon svg{width:24px;height:24px;stroke:#dc2626;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.login-error-title{font-size:15px;font-weight:600;color:#111;margin-bottom:6px}\n.login-error-msg{font-size:13px;color:#6b7280;line-height:1.6;margin-bottom:1.25rem}\n\n/* PROCESSING */\n.proc-wrap{padding:3rem 2rem;max-width:500px;margin:0 auto;text-align:center}\n.proc-icon{width:80px;height:80px;border-radius:50%;background:#eff6ff;display:flex;align-items:center;justify-content:center;margin:0 auto 1.5rem}\n.proc-icon svg{width:36px;height:36px;stroke:#2563eb;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n.proc-title{font-size:20px;font-weight:600;color:#111;margin-bottom:8px}\n.proc-sub{font-size:14px;color:#6b7280;margin-bottom:2rem;line-height:1.6}\n.psteps{text-align:left;max-width:260px;margin:0 auto}\n.pstep{display:flex;align-items:center;gap:12px;padding:7px 0}\n.pico{width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:12px;font-weight:600}\n.pico.ok{background:#e8f5e9;color:#1a7c42}\n.pico.spin{background:#eff6ff}\n.pico.wait{background:#f3f4f6;color:#9ca3af}\n.plbl{font-size:14px;color:#111}\n.plbl.muted{color:#9ca3af}\n\n/* SUCCESS */\n.suc-wrap{padding:3rem 2rem;max-width:560px;margin:0 auto;text-align:center}\n.suc-icon{width:72px;height:72px;border-radius:50%;background:#e8f5e9;display:flex;align-items:center;justify-content:center;margin:0 auto 1.25rem}\n.suc-icon svg{width:36px;height:36px;stroke:#1a7c42;fill:none;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}\n.suc-title{font-size:22px;font-weight:700;color:#111;margin-bottom:6px}\n.suc-sub{font-size:14px;color:#6b7280;margin-bottom:1.5rem}\n.dek{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:1rem 1.25rem;text-align:left;margin-bottom:1.5rem}\n.dek-row{display:flex;justify-content:space-between;align-items:center;font-size:13px;padding:7px 0;border-bottom:1px solid #f3f4f6}\n.dek-row:last-child{border:none;padding-top:10px}\n.dek-lbl{color:#6b7280}\n.dek-val{color:#111;font-weight:600;text-align:right}\n.dek-ref{font-family:monospace;font-size:12px;color:#9ca3af}\n.dekont-img{width:100%;border-radius:10px;border:1px solid #e5e7eb;margin-bottom:1.5rem;display:none}\n.suc-btns{display:flex;flex-direction:column;gap:10px}\n.btn-pri{width:100%;padding:13px;background:#2563eb;color:#fff;border:none;border-radius:12px;font-size:15px;font-weight:600;cursor:pointer;font-family:inherit}\n.btn-pri:hover{opacity:.88}\n.btn-sec{width:100%;padding:11px;background:#fff;color:#374151;border:1px solid #e5e7eb;border-radius:12px;font-size:14px;cursor:pointer;font-family:inherit}\n.btn-sec:hover{background:#f9fafb}\n.limit-info{background:#f0f9ff;border:1px solid #bae6fd;border-radius:10px;padding:10px 14px;font-size:12px;color:#0369a1;margin-bottom:1.25rem}\n/* iframe modu — nav gizle */\n.iframe-mode nav.nav { display: none !important; }\n.iframe-mode .wrap   { padding-top: 16px; }\n/* DEBUG PANEL */\n.dbg-panel{position:fixed;bottom:0;left:0;right:0;background:#0f172a;border-top:2px solid #334155;z-index:9999;font-family:monospace;font-size:11px;max-height:40vh;display:flex;flex-direction:column}\n.dbg-bar{display:flex;align-items:center;padding:5px 10px;gap:8px;cursor:pointer;user-select:none;background:#1e293b;flex-shrink:0}\n.dbg-bar-title{color:#94a3b8;font-size:11px;font-weight:600;letter-spacing:.04em}\n.dbg-badge{background:#2563eb;color:#fff;border-radius:10px;padding:1px 7px;font-size:10px;margin-left:4px}\n.dbg-clear{margin-left:auto;color:#64748b;cursor:pointer;font-size:10px;padding:2px 8px;border:1px solid #334155;border-radius:4px;background:none}\n.dbg-clear:hover{color:#e2e8f0}\n.dbg-body{overflow-y:auto;flex:1;padding:8px 10px;display:none;gap:6px;flex-direction:column}\n.dbg-panel.open .dbg-body{display:flex}\n.dbg-entry{border-radius:6px;overflow:hidden;border:1px solid #1e293b}\n.dbg-entry-hd{display:flex;align-items:center;gap:8px;padding:4px 8px;cursor:pointer}\n.dbg-entry-hd:hover{filter:brightness(1.1)}\n.dbg-req{background:#172033}.dbg-res-ok{background:#14281f}.dbg-res-err{background:#2d1515}\n.dbg-method{font-weight:700;font-size:10px;color:#7dd3fc}\n.dbg-url{color:#94a3b8;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.dbg-status{font-size:10px;font-weight:700;margin-left:auto;white-space:nowrap}\n.dbg-status.ok{color:#4ade80}.dbg-status.err{color:#f87171}\n.dbg-ts{color:#475569;font-size:10px;white-space:nowrap}\n.dbg-body-content{background:#0a0f1e;padding:8px 10px;font-size:10px;color:#cbd5e1;white-space:pre-wrap;word-break:break-all;display:none;max-height:120px;overflow-y:auto}\n.dbg-entry.expanded .dbg-body-content{display:block}\n</style>\n</head>\n<body>\n\n<!-- DEBUG PANEL -->\n<div class=\"dbg-panel\" id=\"dbg-panel\">\n  <div class=\"dbg-bar\" onclick=\"dbgToggle()\">\n    <span class=\"dbg-bar-title\">▶ DEBUG</span>\n    <span class=\"dbg-badge\" id=\"dbg-count\">0</span>\n    <button class=\"dbg-clear\" onclick=\"event.stopPropagation();dbgClear()\">Temizle</button>\n  </div>\n  <div class=\"dbg-body\" id=\"dbg-body\"></div>\n</div>\n\n<nav class=\"nav\">\n  <div class=\"nav-logo\">\n    <div class=\"nav-logo-icon\">\n      <svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg>\n    </div>\n    <span class=\"nav-brand\">PayPanel</span>\n  </div>\n  <div class=\"nav-tabs\">\n    <div class=\"nav-tab\" id=\"tab-home\" onclick=\"showPage('home')\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z\"/></svg>Anasayfa\n    </div>\n    <div class=\"nav-tab\" id=\"tab-dep\" onclick=\"showPage('deposit')\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M12 19V5M5 12l7 7 7-7\"/></svg>Para Yatır\n    </div>\n    <div class=\"nav-tab\" onclick=\"alert('Yakında')\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12l7-7 7 7\"/></svg>Para Çek\n    </div>\n    <div class=\"nav-tab\" onclick=\"alert('Yakında')\">\n      <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 6v6l4 2\"/></svg>İşlem Geçmişi\n    </div>\n  </div>\n  <div class=\"nav-right\">\n    <div>\n      <div class=\"nav-bal-amt\" id=\"nav-bal\">3.500,00 TRY</div>\n      <div class=\"nav-bal-lbl\">Bakiye</div>\n    </div>\n    <div class=\"avatar\">AG</div>\n  </div>\n</nav>\n\n<!-- HOME -->\n<div class=\"page active\" id=\"page-home\">\n  <div class=\"wrap\">\n    <div class=\"greeting\">Hoş geldin, Ayşe Güneş</div>\n    <div class=\"sub\">İşlemlerini buradan yönetebilirsin.</div>\n    <div class=\"bal-card\">\n      <div class=\"bal-icon\"><svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg></div>\n      <div><div class=\"bal-lbl\">Bakiyeniz</div><div class=\"bal-amt\" id=\"home-bal\">3.500,00 TRY</div></div>\n    </div>\n    <div class=\"home-actions\">\n      <button class=\"hbtn hbtn-d\" onclick=\"showPage('deposit')\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M12 19V5M5 12l7 7 7-7\"/></svg>Para Yatır\n      </button>\n      <button class=\"hbtn hbtn-w\" onclick=\"alert('Yakında')\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12l7-7 7 7\"/></svg>Para Çek\n      </button>\n    </div>\n    <div class=\"txn-hd\">\n      <div class=\"txn-title\">Son İşlemler</div>\n      <div style=\"font-size:13px;color:#2563eb;cursor:pointer\">Tümünü gör →</div>\n    </div>\n    <div class=\"txn-list\" id=\"txn-list\"></div>\n  </div>\n</div>\n\n<!-- DEPOSIT — Adım 1: Yöntem Seçimi -->\n<div class=\"page\" id=\"page-deposit\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('home')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 19V5M5 12l7 7 7-7\"/></svg></div>\n      <div class=\"page-title\">Para Yatır</div>\n    </div>\n    <div class=\"page-sub\">Yatırma yönteminizi seçin.</div>\n    <div class=\"method-grid\">\n      <div class=\"method-opt\" id=\"m-havale\" onclick=\"pickMethod('havale')\">\n        <svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg>\n        <span>Havale / EFT</span>\n      </div>\n      <div class=\"method-opt\" id=\"m-kripto\" onclick=\"pickMethod('kripto')\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M9 8h6M9 12h6M9 16h4\"/><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/></svg>\n        <span>Kripto</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- DEPOSIT — Adım 2: Tutar -->\n<div class=\"page\" id=\"page-dep-amount\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('dep-amount')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 19V5M5 12l7 7 7-7\"/></svg></div>\n      <div class=\"page-title\" id=\"dep-amt-title\">Tutar Girin</div>\n    </div>\n    <div class=\"page-sub\" id=\"dep-amt-sub\">Yatırmak istediğiniz tutarı seçin veya girin.</div>\n    <div class=\"card-box\">\n      <div class=\"amt-grid\">\n        <div class=\"amt-opt\" onclick=\"selAmt(100,this)\">₺100</div>\n        <div class=\"amt-opt\" onclick=\"selAmt(250,this)\">₺250</div>\n        <div class=\"amt-opt\" onclick=\"selAmt(500,this)\">₺500</div>\n        <div class=\"amt-opt\" onclick=\"selAmt(1000,this)\">₺1.000</div>\n        <div class=\"amt-opt\" onclick=\"selAmt(2500,this)\">₺2.500</div>\n        <div class=\"amt-opt\" onclick=\"selAmt(5000,this)\">₺5.000</div>\n      </div>\n      <div class=\"amt-custom\">\n        <span>₺</span>\n        <input id=\"custom-amt\" type=\"number\" placeholder=\"Tutar girin (min. 50)\" min=\"50\" oninput=\"customAmt(this)\">\n      </div>\n    </div>\n    <div class=\"card-box\" id=\"kyc-box\" style=\"margin-top:12px\">\n      <div style=\"font-size:13px;font-weight:600;color:#374151;margin-bottom:10px\">Kimlik Bilgileri</div>\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px\">\n        <input id=\"kyc-first\" type=\"text\" placeholder=\"Ad\" style=\"padding:10px 12px;font-size:14px;border:1px solid #e5e7eb;border-radius:10px;outline:none\">\n        <input id=\"kyc-last\"  type=\"text\" placeholder=\"Soyad\" style=\"padding:10px 12px;font-size:14px;border:1px solid #e5e7eb;border-radius:10px;outline:none\">\n      </div>\n      <input id=\"kyc-tc\" type=\"text\" inputmode=\"numeric\" maxlength=\"11\" placeholder=\"TC Kimlik No\" style=\"width:100%;margin-top:10px;padding:10px 12px;font-size:14px;border:1px solid #e5e7eb;border-radius:10px;outline:none\">\n      <input id=\"kyc-phone\" type=\"tel\" placeholder=\"Telefon (05XX XXX XX XX)\" style=\"width:100%;margin-top:10px;padding:10px 12px;font-size:14px;border:1px solid #e5e7eb;border-radius:10px;outline:none\">\n    </div>\n    <div class=\"err-msg\" id=\"dep-err\"></div>\n    <button class=\"submit-btn\" onclick=\"depositNext()\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n      Devam Et\n    </button>\n  </div>\n</div>\n\n\n<!-- HAVALE MANUEL -->\n<div class=\"page\" id=\"page-havale\">\n  <div class=\"wrap\" style=\"max-width:520px;padding-bottom:52px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('dep-amount')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg></div>\n      <div class=\"page-title\">Havale / EFT</div>\n    </div>\n    <div class=\"page-sub\">Aşağıdaki hesaba havale yapın, ardından \"Yatırdım\" butonuna basın.</div>\n    <div class=\"card-box\" id=\"havale-info-box\" style=\"margin-bottom:1rem\">\n      <div style=\"font-size:13px;color:#6b7280;text-align:center;padding:16px\">Hesap bilgileri yükleniyor...</div>\n    </div>\n    <div class=\"err-msg\" id=\"havale-err\"></div>\n    <div id=\"havale-actions\" style=\"display:none\">\n      <button class=\"submit-btn\" onclick=\"confirmHavale()\" style=\"background:#16a34a\">\n        <svg viewBox=\"0 0 24 24\" style=\"width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2.5\"><path d=\"M20 6L9 17l-5-5\"/></svg>\n        Yatırdım\n      </button>\n      <div style=\"margin-top:.75rem;font-size:12px;color:#6b7280;text-align:center\">İşlem 5-30 dakika içinde onaylanır.</div>\n    </div>\n  </div>\n</div>\n<!-- KRİPTO -->\n<div class=\"page\" id=\"page-kripto\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('dep-amount')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9 8h5a2 2 0 010 4H9v4h5a2 2 0 010 4\"/><line x1=\"12\" y1=\"6\" x2=\"12\" y2=\"8\"/><line x1=\"12\" y1=\"20\" x2=\"12\" y2=\"22\"/></svg></div>\n      <div class=\"page-title\">Kripto ile Yatır</div>\n    </div>\n    <div class=\"page-sub\">Aşağıdaki adrese transfer yapın.</div>\n    <div id=\"kripto-info-box\">\n      <div style=\"font-size:13px;color:#6b7280;text-align:center;padding:24px\">⏳ Yükleniyor...</div>\n    </div>\n    <div class=\"err-msg\" id=\"kripto-err\"></div>\n    <div id=\"kripto-actions\" style=\"display:none;margin-top:12px\">\n      <button class=\"submit-btn\" id=\"kripto-confirm-btn\" onclick=\"confirmKripto()\" style=\"background:#16a34a\">\n        <svg viewBox=\"0 0 24 24\" style=\"width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2.5\"><path d=\"M20 6L9 17l-5-5\"/></svg>\n        <span id=\"kripto-confirm-label\">Gönderdim</span>\n      </button>\n    </div>\n  </div>\n</div>\n\n<!-- İŞLEM SONUCU -->\n<div class=\"page\" id=\"page-result\">\n  <div class=\"proc-wrap\">\n    <div id=\"result-icon\" class=\"proc-icon\"></div>\n    <div class=\"proc-title\" id=\"result-title\"></div>\n    <div class=\"proc-sub\" id=\"result-sub\"></div>\n    <div style=\"margin-top:2rem\">\n      <button onclick=\"closeWidget()\" class=\"submit-btn\" style=\"max-width:240px;margin:0 auto\">\n        ✕ Kapat\n      </button>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL ONAYI BEKLENİYOR -->\n<!-- ÇEKİM — Adım 1: Yöntem -->\n<div class=\"page\" id=\"page-withdraw\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"closeWidget()\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2v20M17 7l-5-5-5 5\"/></svg></div>\n      <div class=\"page-title\">Para Çek</div>\n    </div>\n    <div class=\"page-sub\">Çekim yönteminizi seçin.</div>\n    <div class=\"method-grid\">\n      <div class=\"method-opt\" onclick=\"pickWdMethod('havale')\">\n        <svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg>\n        <span>Havale / EFT</span>\n      </div>\n      <div class=\"method-opt\" onclick=\"pickWdMethod('kripto')\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M9 8h6M9 12h6M9 16h4\"/><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/></svg>\n        <span>Kripto</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ÇEKİM — Adım 2: Tutar -->\n<div class=\"page\" id=\"page-wd-amount\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('withdraw')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2v20M17 7l-5-5-5 5\"/></svg></div>\n      <div class=\"page-title\" id=\"wd-amt-title\">Tutar Girin</div>\n    </div>\n    <div class=\"page-sub\" id=\"wd-balance-info\">Çekmek istediğiniz tutarı seçin veya girin.</div>\n    <div class=\"card-box\">\n      <div class=\"amt-grid\" id=\"wd-chips\">\n        <div class=\"amt-opt\" onclick=\"wdChip(100,this)\">₺100</div>\n        <div class=\"amt-opt\" onclick=\"wdChip(250,this)\">₺250</div>\n        <div class=\"amt-opt\" onclick=\"wdChip(500,this)\">₺500</div>\n        <div class=\"amt-opt\" onclick=\"wdChip(1000,this)\">₺1.000</div>\n        <div class=\"amt-opt\" onclick=\"wdChip(2500,this)\">₺2.500</div>\n        <div class=\"amt-opt\" onclick=\"wdChip(5000,this)\">₺5.000</div>\n      </div>\n      <div class=\"amt-custom\">\n        <span>₺</span>\n        <input id=\"wd-amount\" type=\"number\" placeholder=\"Tutar girin (min. 50)\" min=\"50\" oninput=\"wdClearChips()\">\n      </div>\n    </div>\n    <div class=\"err-msg\" id=\"wd-amt-err\"></div>\n    <button class=\"submit-btn\" onclick=\"wdAmtNext()\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n      Devam Et\n    </button>\n  </div>\n</div>\n\n<!-- ÇEKİM — Adım 3: Havale Bilgileri -->\n<div class=\"page\" id=\"page-wd-details\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('wd-amount')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg></div>\n      <div class=\"page-title\">Banka Bilgileri</div>\n    </div>\n    <div class=\"page-sub\" id=\"wd-details-sub\">Ödemenin yapılacağı hesap bilgilerini girin.</div>\n    <div class=\"card-box\" style=\"display:flex;flex-direction:column;gap:14px\">\n      <div>\n        <div style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px\">Ad Soyad</div>\n        <input id=\"wd-name\" type=\"text\" placeholder=\"Hesap sahibinin adı\"\n          style=\"width:100%;border:none;border-bottom:1.5px solid #e5e7eb;outline:none;font-size:14px;padding:6px 0;background:transparent;box-sizing:border-box\">\n      </div>\n      <div>\n        <div style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px\">IBAN</div>\n        <input id=\"wd-iban\" type=\"text\" placeholder=\"TR00 0000 0000 0000 0000 0000 00\"\n          style=\"width:100%;border:none;border-bottom:1.5px solid #e5e7eb;outline:none;font-size:14px;font-family:monospace;padding:6px 0;background:transparent;box-sizing:border-box\">\n      </div>\n      <div style=\"background:#eff6ff;border-radius:8px;padding:10px 12px;font-size:12px;color:#1e40af\">\n        ℹ️ Çekim tutarı: <strong id=\"wd-confirm-amt\"></strong>\n      </div>\n    </div>\n    <div class=\"err-msg\" id=\"wd-err\"></div>\n    <button class=\"submit-btn\" onclick=\"submitWithdraw()\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n      Çekim Talebi Oluştur\n    </button>\n  </div>\n</div>\n\n<!-- ÇEKİM — Adım 3: Kripto Bilgileri -->\n<div class=\"page\" id=\"page-wd-kripto\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('wd-amount')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 8h6M9 12h6M9 16h4\"/><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/></svg></div>\n      <div class=\"page-title\">Kripto Çekim</div>\n    </div>\n    <div class=\"page-sub\" id=\"wd-kripto-sub\">Cüzdan adresinizi ve coin türünü girin.</div>\n    <div class=\"card-box\" style=\"display:flex;flex-direction:column;gap:14px\">\n      <div>\n        <div style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;margin-bottom:8px\">Coin Seçin</div>\n        <div style=\"display:flex;gap:8px\">\n          <div class=\"method-opt\" id=\"wdc-BTC\" onclick=\"selectWdCoin('BTC')\" style=\"flex:1;padding:10px 6px;font-size:13px\">BTC</div>\n          <div class=\"method-opt\" id=\"wdc-ETH\" onclick=\"selectWdCoin('ETH')\" style=\"flex:1;padding:10px 6px;font-size:13px\">ETH</div>\n          <div class=\"method-opt\" id=\"wdc-USDT\" onclick=\"selectWdCoin('USDT')\" style=\"flex:1;padding:10px 6px;font-size:13px\">USDT</div>\n        </div>\n      </div>\n      <div>\n        <div style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px\">Cüzdan Adresi</div>\n        <input id=\"wd-wallet\" type=\"text\" placeholder=\"0x... veya bc1...\"\n          style=\"width:100%;border:none;border-bottom:1.5px solid #e5e7eb;outline:none;font-size:13px;font-family:monospace;padding:6px 0;background:transparent;box-sizing:border-box\">\n      </div>\n      <div style=\"background:#eff6ff;border-radius:8px;padding:10px 12px;font-size:12px;color:#1e40af\">\n        ℹ️ Çekim tutarı: <strong id=\"wd-kripto-confirm-amt\"></strong>\n      </div>\n    </div>\n    <div class=\"err-msg\" id=\"wd-kripto-err\"></div>\n    <button class=\"submit-btn\" onclick=\"submitWithdrawKripto()\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n      Çekim Talebi Oluştur\n    </button>\n  </div>\n</div>\n\n<div class=\"page\" id=\"page-waiting\">\n  <div class=\"proc-wrap\">\n    <div class=\"proc-icon\">\n      <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 6v6l4 2\"/></svg>\n    </div>\n    <div class=\"proc-title\">Onay Bekleniyor</div>\n    <div class=\"proc-sub\">Ödemeniz alındı, panel onayı bekleniyor.<br>Bu ekranı kapatmayın.</div>\n    <div style=\"margin-top:2rem;display:flex;justify-content:center\">\n      <div class=\"spin-ring-lg\"></div>\n    </div>\n    <div style=\"margin-top:1.5rem;font-size:13px;color:#9ca3af;text-align:center\">Tahmini süre: 5–30 dakika</div>\n  </div>\n</div>\n\n<!-- SUCCESS -->\n<div class=\"page\" id=\"page-suc\">\n  <div class=\"suc-wrap\">\n    <div class=\"suc-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M20 6L9 17l-5-5\"/></svg></div>\n    <div class=\"suc-title\">Para Yatırma Başarılı!</div>\n    <div class=\"suc-sub\" id=\"suc-sub\"></div>\n    <img id=\"dekont-img\" class=\"dekont-img\" alt=\"Dekont\">\n    <div class=\"dek\" id=\"dek\"></div>\n    <div class=\"suc-btns\">\n      <button class=\"btn-pri\" onclick=\"showPage('home')\">Ana Sayfaya Dön</button>\n      <button class=\"btn-sec\" id=\"dek-dl-btn\">Dekontu İndir (PNG)</button>\n    </div>\n  </div>\n</div>\n\n<script>\n/* ════════════════════════\n   BANK LOGOS\n════════════════════════ */\n\n/* ════════════════════════\n   CONFIG\n════════════════════════ */\nfunction apiBase(){\n  // URL param'a bak (?engine_url=...), yoksa aynı origin'i kullan\n  const urlParam = new URLSearchParams(window.location.search).get('engine_url');\n  if(urlParam) return urlParam.replace(/\\/+$/,'');\n  return window.location.origin;\n}\nconst OPERATOR_IBAN = \"TR33 0006 1005 1978 6457 8413 26\";\n\n/* ════════════════════════\n   MOCK DATA\n════════════════════════ */\nlet TXNS = [\n  {name:'Para Yatırma',time:'3 dk önce',status:'proc',amt:2500},\n  {name:'Para Yatırma',time:'3 dk önce',status:'appr',amt:2500},\n  {name:'Para Yatırma',time:'3 dk önce',status:'proc',amt:2500},\n  {name:'Para Yatırma',time:'4 dk önce',status:'pend',amt:2500},\n  {name:'Para Yatırma',time:'4 dk önce',status:'proc',amt:1000},\n];\nlet balance = 3500;\n\n/* ════════════════════════\n   DEBUG\n════════════════════════ */\nvar _dbgEntries = [];\nfunction dbgToggle(){\n  var p = document.getElementById('dbg-panel');\n  p.classList.toggle('open');\n  var t = p.querySelector('.dbg-bar-title');\n  t.textContent = p.classList.contains('open') ? '▼ DEBUG' : '▶ DEBUG';\n}\nfunction dbgClear(){\n  _dbgEntries = [];\n  document.getElementById('dbg-body').innerHTML = '';\n  document.getElementById('dbg-count').textContent = '0';\n}\nfunction dbgLog(dir, method, url, statusOrNull, reqBody, resBody){\n  var ts = new Date().toISOString().substr(11,12);\n  var shortUrl = url.replace(apiBase(),'');\n  var isErr = statusOrNull !== null && statusOrNull >= 400;\n  var entryId = 'dbge' + Date.now() + Math.random().toString(36).substr(2,4);\n\n  var hdClass = dir === 'req' ? 'dbg-req' : (isErr ? 'dbg-res-err' : 'dbg-res-ok');\n  var statusHtml = statusOrNull !== null\n    ? '<span class=\"dbg-status '+(isErr?'err':'ok')+'\">'+statusOrNull+'</span>' : '';\n  var bodyStr = '';\n  try{ bodyStr = typeof resBody === 'string' ? resBody : JSON.stringify(reqBody||resBody, null, 2); }catch(e){ bodyStr = String(reqBody||resBody); }\n\n  var html = '<div class=\"dbg-entry\" id=\"'+entryId+'\">'\n    + '<div class=\"dbg-entry-hd '+hdClass+'\" onclick=\"document.getElementById(\\''+entryId+'\\').classList.toggle(\\'expanded\\')\">'\n    + '<span class=\"dbg-method\">'+(dir==='req'?'→ '+method:'← '+method)+'</span>'\n    + '<span class=\"dbg-url\">'+shortUrl+'</span>'\n    + statusHtml\n    + '<span class=\"dbg-ts\">'+ts+'</span>'\n    + '</div>'\n    + '<div class=\"dbg-body-content\">'+escHtml(bodyStr)+'</div>'\n    + '</div>';\n\n  var body = document.getElementById('dbg-body');\n  body.insertAdjacentHTML('afterbegin', html);\n  _dbgEntries.push(entryId);\n  document.getElementById('dbg-count').textContent = _dbgEntries.length;\n}\nfunction escHtml(s){ return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }\n\nasync function dbgFetch(url, opts){\n  var method = (opts&&opts.method)||'GET';\n  var reqBody = null;\n  try{ reqBody = opts&&opts.body ? JSON.parse(opts.body) : null; }catch(e){}\n  dbgLog('req', method, url, null, reqBody, null);\n  var r = await fetch(url, opts);\n  var clone = r.clone();\n  var resText = await clone.text();\n  var resBody = null;\n  try{ resBody = JSON.parse(resText); }catch(e){ resBody = resText; }\n  dbgLog('res', method, url, r.status, null, resBody);\n  return r;\n}\n// URL parametrelerinden oku (iframe/embed modunda)\nconst _urlp       = new URLSearchParams(window.location.search);\nconst _urlAmt     = parseFloat(_urlp.get('amount'))     || 0;\nconst _urlMerchant= _urlp.get('merchant_id') || window.__KIPAY_MERCHANT_ID || null;\nconst _urlUser    = _urlp.get('user_id')     || null;\nconst _urlPage    = _urlp.get('page')        || null;\nconst _urlMethod  = _urlp.get('method')      || null;\nconst _urlBalance = _urlp.has('balance') ? parseFloat(_urlp.get('balance')) : null;\n// KYC — panel initiate TC kimlik dahil userInfo'yu zorunlu tutar. Merchant embed\n// ederken URL ile geçebilir; geçmezse standalone formda kullanıcı girer.\nconst _urlTc      = _urlp.get('identity_number') || _urlp.get('tc') || '';\nconst _urlFirst   = _urlp.get('first_name') || '';\nconst _urlLast    = _urlp.get('last_name')  || '';\nconst _urlPhone   = _urlp.get('phone')      || '';\nconst _kycFromUrl = !!(_urlTc && _urlFirst && _urlLast && _urlPhone);\n\nlet S = {method:_urlMethod||null, amt:_urlAmt||0, bank:null, sessionId:null, dekontB64:null,\n         merchantId:_urlMerchant, userId:_urlUser,\n         tc:_urlTc, firstName:_urlFirst, lastName:_urlLast, phone:_urlPhone};\n\n// initiate gövdesine eklenecek KYC alanları\nfunction kycBody(){\n  return {\n    identity_number: S.tc || '',\n    first_name:      S.firstName || '',\n    last_name:       S.lastName || '',\n    phone:           S.phone || '',\n  };\n}\n// TC 11 hane, telefon +90XXXXXXXXXX; formdaki alanlardan S'e al ve doğrula\nfunction collectKyc(){\n  if(_kycFromUrl) return true;  // merchant zaten geçmiş\n  const g=id=>(document.getElementById(id)?.value||'').trim();\n  S.tc=g('kyc-tc'); S.firstName=g('kyc-first'); S.lastName=g('kyc-last');\n  let ph=g('kyc-phone').replace(/\\s/g,'');\n  if(ph && !ph.startsWith('+')){ ph = ph.startsWith('0') ? '+9'+ph : '+90'+ph; }\n  S.phone=ph;\n  const err=document.getElementById('dep-err');\n  if(!/^[0-9]{11}$/.test(S.tc)){ if(err)err.textContent='Geçerli bir TC Kimlik No girin (11 hane).'; return false; }\n  if(!S.firstName||!S.lastName){ if(err)err.textContent='Ad ve soyad zorunlu.'; return false; }\n  if(!/^\\+90[0-9]{10}$/.test(S.phone)){ if(err)err.textContent='Telefon +90XXXXXXXXXX formatında olmalı.'; return false; }\n  return true;\n}\nlet selectedAmt = _urlAmt || 0;\n\n// iframe modunda navbar ve engine bar'ı gizle\nif (_urlPage) {\n  document.documentElement.classList.add('iframe-mode');\n}\n\n// URL'den method + amount gelirse → direkt ödeme adımına atla (seçim sayfasını geç)\nif (_urlMethod && _urlAmt > 0) {\n  document.addEventListener('DOMContentLoaded', () => {\n    S.method = _urlMethod;\n    S.amt    = _urlAmt;\n    selectedAmt = _urlAmt;\n    // Yönteme göre direkt ilgili sayfaya git\n    if      (_urlMethod === 'kripto')       startKripto();\n    else if (_urlMethod === 'havale')       startHavaleManuel();\n  });\n} else if (_urlPage === 'deposit') {\n  document.addEventListener('DOMContentLoaded', () => showPage('deposit'));\n} else if (_urlPage === 'withdraw') {\n  document.addEventListener('DOMContentLoaded', () => {\n    showPage('withdraw');\n    if(_urlBalance !== null){\n      var el = document.getElementById('wd-balance-info');\n      if(el) el.textContent = 'Kullanılabilir bakiye: ₺' + fmt(_urlBalance) + ' — çekmek istediğiniz tutarı girin.';\n    }\n  });\n}\n\n/* ════════════════════════\n   UTILS\n════════════════════════ */\nfunction fmt(n){return n.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})}\nfunction updateBal(){const t=fmt(balance)+' TRY';document.getElementById('nav-bal').textContent=t;document.getElementById('home-bal').textContent=t}\nfunction statusBadge(s){const m={proc:{c:'b-proc',t:'Processing'},appr:{c:'b-appr',t:'Approved'},pend:{c:'b-pend',t:'Pending'},rej:{c:'b-rej',t:'Rejected'}};const d=m[s]||m.pend;return`<span class=\"badge ${d.c}\">${d.t}</span>`}\nfunction renderTxns(){document.getElementById('txn-list').innerHTML=TXNS.map(t=>`<div class=\"txn-card\"><div class=\"txn-l\"><div class=\"txn-ico\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 19V5M5 12l7 7 7-7\"/></svg></div><div><div class=\"txn-name\">${t.name}</div><div class=\"txn-time\">${t.time}</div></div></div><div class=\"txn-r\">${statusBadge(t.status)}<div class=\"txn-amt\">₺${fmt(t.amt)}</div></div></div>`).join('')}\n\nfunction notifySuccess(txId) {\n  // iframe modunda parent'a bildir — modal KAPATILMAZ, SSE callback bekler\n  if (_urlPage) {\n    try {\n      parent.postMessage({\n        type: 'pp-confirmed',\n        transaction_id: txId,\n        amount: S.amt || 0,\n        method: S.method || 'havale',\n      }, '*');\n    } catch(e) {}\n  }\n}\n\nfunction closeWidget(){\n  try{ parent.postMessage({type:'pp-close'},'*'); }catch(e){}\n}\n\n/* ════════════════════════\n   ÇEKİM\n════════════════════════ */\nfunction pickWdMethod(m){\n  S.wdMethod = m;\n  document.getElementById('wd-amount').value = '';\n  wdClearChips();\n  var title = document.getElementById('wd-amt-title');\n  if(title) title.textContent = m === 'kripto' ? 'Kripto Çekim Tutarı' : 'Çekim Tutarı';\n  showPage('wd-amount');\n}\n\nfunction wdChip(v, el){\n  document.getElementById('wd-amount').value = v;\n  document.querySelectorAll('#wd-chips .amt-opt').forEach(function(b){ b.classList.remove('active'); });\n  el.classList.add('active');\n}\nfunction wdClearChips(){\n  document.querySelectorAll('#wd-chips .amt-opt').forEach(function(b){ b.classList.remove('active'); });\n}\n\nfunction wdAmtNext(){\n  var amt = parseFloat(document.getElementById('wd-amount').value) || 0;\n  var err = document.getElementById('wd-amt-err');\n  err.textContent = '';\n  if(amt < 50){ err.textContent = 'Minimum tutar ₺50 olmalıdır.'; return; }\n  if(_urlBalance !== null && amt > _urlBalance){ err.textContent = 'Bakiyenizi aşıyorsunuz. Mevcut bakiye: ₺'+fmt(_urlBalance); return; }\n  S.wdAmt = amt;\n  if(S.wdMethod === 'kripto'){\n    var el = document.getElementById('wd-kripto-confirm-amt');\n    if(el) el.textContent = '₺' + fmt(amt);\n    S.wdCoin = null;\n    document.querySelectorAll('[id^=\"wdc-\"]').forEach(function(b){ b.classList.remove('sel'); });\n    showPage('wd-kripto');\n  } else {\n    var el = document.getElementById('wd-confirm-amt');\n    if(el) el.textContent = '₺' + fmt(amt);\n    var sub = document.getElementById('wd-details-sub');\n    if(sub) sub.textContent = '₺' + fmt(amt) + ' çekim için hesap bilgilerinizi girin.';\n    showPage('wd-details');\n  }\n}\n\nfunction selectWdCoin(coin){\n  S.wdCoin = coin;\n  document.querySelectorAll('[id^=\"wdc-\"]').forEach(function(b){ b.classList.remove('sel'); });\n  var el = document.getElementById('wdc-'+coin);\n  if(el) el.classList.add('sel');\n}\n\nasync function submitWithdrawKripto(){\n  var coin   = S.wdCoin;\n  var wallet = document.getElementById('wd-wallet').value.trim();\n  var err    = document.getElementById('wd-kripto-err');\n  err.textContent = '';\n  if(!coin)         { err.textContent = 'Coin türü seçiniz.'; return; }\n  if(!wallet)       { err.textContent = 'Cüzdan adresi giriniz.'; return; }\n  await _doWithdraw({ currency: coin, iban: wallet, account_name: coin + ' Withdrawal', err_el: 'wd-kripto-err', btn_sel: '#page-wd-kripto .submit-btn' });\n}\n\nasync function submitWithdraw(){\n  var iban = document.getElementById('wd-iban').value.trim();\n  var name = document.getElementById('wd-name').value.trim();\n  var err  = document.getElementById('wd-err');\n  err.textContent = '';\n  if(!name)             { err.textContent = 'Ad soyad giriniz.'; return; }\n  if(iban.length < 10)  { err.textContent = 'Geçerli bir IBAN giriniz.'; return; }\n  await _doWithdraw({ currency: 'TRY', iban: iban, account_name: name, err_el: 'wd-err', btn_sel: '#page-wd-details .submit-btn' });\n}\n\nasync function _doWithdraw({ currency, iban, account_name, err_el, btn_sel }){\n  var amt = S.wdAmt || 0;\n  var err = document.getElementById(err_el);\n  if(!amt){ if(err) err.textContent = 'Tutar bilgisi eksik.'; return; }\n\n  var btn = btn_sel ? document.querySelector(btn_sel) : null;\n  if(btn){ btn.disabled=true; btn.textContent='Gönderiliyor...'; }\n\n  try{\n    const r = await fetch(apiBase()+'/api/payment/withdrawal', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({\n        merchant_id:  S.merchantId || 'demo',\n        user_id:      S.userId    || 'demo',\n        amount:       amt,\n        currency:     currency,\n        method:       currency === 'TRY' ? 'havale' : 'kripto',\n        iban:         iban,\n        account_name: account_name,\n      })\n    });\n    const d = await r.json();\n    if(!r.ok) throw new Error(d.detail || 'Çekim talebi gönderilemedi.');\n\n    var txId = d.txId || d.transaction_id || ('wd_'+Date.now());\n    try{ parent.postMessage({type:'pp-confirmed', transaction_id:txId, amount:amt, method:'withdraw'}, '*'); }catch(e){}\n    showPage('waiting');\n\n  }catch(e){\n    if(err) err.textContent = e.message;\n    if(btn){ btn.disabled=false; btn.textContent='Çekim Talebi Oluştur'; }\n  }\n}\n\n// Panel'den sonuç mesajı gelince result sayfasını göster\nwindow.addEventListener('message', function(e){\n  if(!e.data || e.data.type !== 'pp-result') return;\n  var ok = e.data.status === 'APPROVED';\n  var icon = document.getElementById('result-icon');\n  var title = document.getElementById('result-title');\n  var sub   = document.getElementById('result-sub');\n  if(ok){\n    icon.style.background = '#e8f5e9';\n    icon.innerHTML = '<svg viewBox=\"0 0 24 24\" style=\"width:36px;height:36px;stroke:#1a7c42;fill:none;stroke-width:2.5\"><path d=\"M20 6L9 17l-5-5\"/></svg>';\n    title.textContent = 'Ödemeniz Onaylandı!';\n    sub.innerHTML = 'Tutarınız hesabınıza yansıtıldı.<br>Teşekkürler.';\n  } else {\n    icon.style.background = '#fef3f2';\n    icon.innerHTML = '<svg viewBox=\"0 0 24 24\" style=\"width:36px;height:36px;stroke:#dc2626;fill:none;stroke-width:2.5\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"15\" y1=\"9\" x2=\"9\" y2=\"15\"/><line x1=\"9\" y1=\"9\" x2=\"15\" y2=\"15\"/></svg>';\n    title.textContent = e.data.status === 'TIMEOUT' ? 'Süre Doldu' : 'İşlem Reddedildi';\n    sub.innerHTML = 'İşleminiz onaylanamadı.<br>Yeniden denemek için kapatınız.';\n  }\n  showPage('result');\n});\n\nfunction showPage(id){\n  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));\n  document.querySelectorAll('.nav-tab').forEach(t=>t.classList.remove('active'));\n  const el = document.getElementById('page-'+id);\n  if(!el){ console.error('showPage: page not found: page-'+id); return; }\n  el.classList.add('active');\n  const m={home:'tab-home',deposit:'tab-dep','dep-amount':'tab-dep',suc:'tab-dep',havale:'tab-dep',kripto:'tab-dep',waiting:'tab-dep',result:'tab-dep',withdraw:'tab-wd','wd-amount':'tab-wd','wd-details':'tab-wd','wd-kripto':'tab-wd'};\n  const tab=document.getElementById(m[id]);\n  if(tab) tab.classList.add('active');\n  window.scrollTo(0,0);\n}\n\nfunction setBtn(id,loading,txt=''){\n  const b=document.getElementById(id);\n  if(!b) return;\n  b.disabled=loading;\n  if(loading){b.dataset.orig=b.innerHTML;b.innerHTML=`<div class=\"spin-ring\" style=\"border-color:#93c5fd;border-top-color:#fff\"></div> ${txt||'İşleniyor...'}`;}\n  else if(b.dataset.orig) b.innerHTML=b.dataset.orig;\n}\n\n/* ════════════════════════\n   DEPOSIT\n════════════════════════ */\n\n\n/* ── KREDİ KARTI ── */\nlet _cc3dTimer = null;\nlet _ccTransactionId = null;\n\n// Kredi kartı sayfasına girilince tutar göster\n/* ── HAVALE MANUEL ── */\n// IBAN formatla: TR330006... → TR33 0006 ...\nfunction fmtIBAN(iban){\n  return (iban||'').replace(/\\s/g,'').replace(/(.{4})/g,'$1 ').trim();\n}\n\n// expiresAt countdown\nlet _havaleCountdown = null;\nlet _havaleAccountPollTimer = null;\n\nfunction _renderHavaleAccount(box, iban, accName, accBank, expiresAt){\n  window._havaleIban = iban;\n  var ibanFmt = fmtIBAN(iban);\n  var nameRow = accName\n    ? '<div style=\"display:flex;justify-content:space-between;align-items:center;gap:8px;padding-bottom:10px;border-bottom:1px solid #f3f4f6\">'\n      + '<span style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;white-space:nowrap\">Ad Soyad</span>'\n      + '<span id=\"havale-accname\" style=\"font-size:13px;font-weight:600;text-align:right\"></span>'\n      + '</div>'\n    : '';\n  var countdownRow = expiresAt\n    ? '<div style=\"display:flex;justify-content:space-between;align-items:center\">'\n      + '<span style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em\">Kalan Süre</span>'\n      + '<span id=\"havale-countdown\" style=\"font-family:monospace;font-size:13px;font-weight:600;color:#f59e0b\">--:--</span>'\n      + '</div>'\n    : '';\n  box.innerHTML = '<div style=\"display:flex;flex-direction:column;gap:12px\">'\n    + nameRow\n    + '<div style=\"display:flex;justify-content:space-between;align-items:center;gap:8px\">'\n      + '<span style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;white-space:nowrap\">IBAN</span>'\n      + '<div style=\"display:flex;align-items:center;gap:8px;justify-content:flex-end\">'\n        + '<span style=\"font-family:monospace;font-size:12px;font-weight:600\">' + ibanFmt + '</span>'\n        + '<button id=\"iban-copy-btn\" style=\"border:1px solid #e5e7eb;border-radius:6px;padding:3px 10px;font-size:11px;cursor:pointer;background:#f9fafb;white-space:nowrap\">Kopyala</button>'\n      + '</div>'\n    + '</div>'\n    + '<div style=\"display:flex;justify-content:space-between;border-top:1px solid #f3f4f6;padding-top:12px;margin-top:4px\">'\n      + '<span style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em\">Tutar</span>'\n      + '<span style=\"font-size:16px;font-weight:700;color:#2563eb\">₺' + fmt(S.amt) + '</span>'\n    + '</div>'\n    + countdownRow\n    + '</div>';\n  if(accName){\n    var elName = document.getElementById('havale-accname');\n    if(elName) elName.textContent = accName + (accBank ? ' — ' + accBank : '');\n  }\n  var copyBtn = document.getElementById('iban-copy-btn');\n  if(copyBtn){\n    copyBtn.addEventListener('click', function(){\n      var btn = this;\n      function onOk(){ btn.textContent='✓'; setTimeout(function(){ btn.textContent='Kopyala'; },2000); }\n      function onFail(){\n        var ta = document.createElement('textarea');\n        ta.value = window._havaleIban;\n        ta.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0';\n        document.body.appendChild(ta); ta.focus(); ta.select();\n        try{ document.execCommand('copy') ? onOk() : (btn.textContent='!'); }catch(ex){ btn.textContent='!'; }\n        document.body.removeChild(ta);\n      }\n      if(navigator.clipboard && navigator.clipboard.writeText){\n        navigator.clipboard.writeText(window._havaleIban).then(onOk).catch(onFail);\n      } else { onFail(); }\n    });\n  }\n  if(expiresAt) startHavaleCountdown(expiresAt);\n  document.getElementById('havale-actions').style.display = 'block';\n}\n\nfunction _pollForHavaleAccount(txId, box){\n  var started = Date.now();\n  _havaleAccountPollTimer = setInterval(async function(){\n    if(Date.now() - started > 120000){\n      clearInterval(_havaleAccountPollTimer);\n      box.innerHTML = '<div style=\"color:#dc2626;font-size:13px;text-align:center;padding:16px\">Hesap ataması zaman aşımına uğradı. Lütfen tekrar deneyin.</div>';\n      return;\n    }\n    try{\n      var r = await fetch(apiBase()+'/api/payment/status/'+txId);\n      if(!r.ok) return;\n      var tx = await r.json();\n      var iban = tx.ibanWallet || '';\n      if(iban){\n        clearInterval(_havaleAccountPollTimer);\n        _renderHavaleAccount(box, iban, tx.accountName || '', tx.bank || '', tx.expiresAt || '');\n      }\n    }catch(e){}\n  }, 3000);\n}\n\nfunction startHavaleCountdown(expiresAt, elId){\n  clearInterval(_havaleCountdown);\n  const el = document.getElementById(elId || 'havale-countdown');\n  if(!el || !expiresAt) return;\n  function tick(){\n    const secs = Math.max(0, Math.floor((new Date(expiresAt) - Date.now()) / 1000));\n    const m = String(Math.floor(secs/60)).padStart(2,'0');\n    const s = String(secs%60).padStart(2,'0');\n    if(el) el.textContent = `${m}:${s}`;\n    if(secs <= 0){\n      clearInterval(_havaleCountdown);\n      if(el) el.textContent = 'Süre doldu';\n      if(el) el.style.color = '#dc2626';\n    }\n  }\n  tick();\n  _havaleCountdown = setInterval(tick, 1000);\n}\n\nasync function startHavaleManuel(){\n  showPage('havale');\n  clearInterval(_havaleCountdown);\n  clearInterval(_havaleAccountPollTimer);\n  const box = document.getElementById('havale-info-box');\n  box.innerHTML = '<div style=\"font-size:13px;color:#6b7280;text-align:center;padding:16px\">⏳ Hesap bilgileri alınıyor...</div>';\n  S._havaleTransactionId = null;\n  document.getElementById('havale-actions').style.display = 'none';\n\n  try{\n    const r = await dbgFetch(apiBase()+'/api/payment/account', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({\n        merchant_id: S.merchantId||'demo',\n        user_id:     S.userId||'demo',\n        method:      'havale',\n        amount:      S.amt,\n        currency:    'TRY',\n        ...kycBody()\n      })\n    });\n\n    const d = await r.json();\n\n    if(!r.ok){\n      if(d.detail === 'NO_AVAILABLE_ACCOUNT'){\n        box.innerHTML = `<div style=\"text-align:center;padding:20px\">\n          <div style=\"font-size:13px;color:#dc2626;margin-bottom:14px\">❌ Şu anda uygun hesap bulunamadı.<br>Lütfen daha düşük bir tutar deneyin veya sonra tekrar gelin.</div>\n          <button onclick=\"showPage('dep-amount')\" style=\"background:#f3f4f6;color:#374151;border:1px solid #e5e7eb;border-radius:8px;padding:8px 20px;font-size:13px;cursor:pointer\">← Tutarı Değiştir</button>\n        </div>`;\n      } else {\n        box.innerHTML = `<div style=\"color:#dc2626;font-size:13px;text-align:center;padding:16px\">\n          ❌ ${d.detail||'Hesap bilgisi alınamadı. Lütfen tekrar deneyin.'}</div>`;\n      }\n      return;\n    }\n\n    S._havaleTransactionId = d.transaction_id;\n    const iban = d.account?.iban || d.ibanWallet || '';\n\n    if(!iban){\n      if(d.status === 'PENDING' && d.transaction_id){\n        // v2 akışı: hesap claim anında atanıyor — operator atamasını bekle\n        box.innerHTML = '<div style=\"font-size:13px;color:#6b7280;text-align:center;padding:16px\">⏳ Operatör hesap ataması bekleniyor...</div>';\n        _pollForHavaleAccount(d.transaction_id, box);\n      } else {\n        box.innerHTML = '<div style=\"color:#dc2626;font-size:13px;text-align:center;padding:16px\">Uygun hesap bulunamadı.</div>';\n      }\n      return;\n    }\n\n    _renderHavaleAccount(box, iban, d.account?.name || d.accountName || '', d.account?.bank || d.bank || '', d.expires_at);\n\n  }catch(e){\n    console.error('startHavaleManuel:', e);\n    box.innerHTML = '<div style=\"color:#dc2626;font-size:13px;text-align:center;padding:16px\">Bağlantı hatası. Engine çalışıyor mu?</div>';\n  }\n}\n\nasync function confirmHavale(){\n  const err = document.getElementById('havale-err');\n  if(!S._havaleTransactionId){ err.textContent='İşlem başlatılmadı.'; return; }\n  err.textContent = '';\n\n  const btn = document.querySelector('#havale-actions .submit-btn');\n  if(btn){ btn.disabled=true; btn.textContent='Gönderiliyor...'; }\n\n  try{\n    const r = await dbgFetch(apiBase()+'/api/payment/confirm', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({transaction_id: S._havaleTransactionId, note:''})\n    });\n    const d = await r.json();\n    if(!r.ok) throw new Error(d.detail||'Hata');\n  }catch(e){\n    if(btn){ btn.disabled=false; btn.textContent='Yatırdım'; }\n    err.textContent = 'Bildirim gönderilemedi: ' + e.message;\n    return;\n  }\n\n  clearInterval(_havaleCountdown);\n  showPage('waiting');\n  notifySuccess(S._havaleTransactionId);\n}\n\n/* ── KRİPTO ── */\nvar _kriptoLoading = false;\nasync function startKripto(){\n  if(_kriptoLoading) return;  // çift tıklama koruması\n  _kriptoLoading = true;\n\n  showPage('kripto');\n  const box = document.getElementById('kripto-info-box');\n  box.innerHTML = '<div style=\"font-size:13px;color:#6b7280;text-align:center;padding:24px\">⏳ Hesap bilgileri alınıyor...</div>';\n  document.getElementById('kripto-actions').style.display = 'none';\n  document.getElementById('kripto-err').textContent = '';\n  S._kriptoTransactionId = null;\n  S._kriptoCoin = null;\n  S._kriptoData = null;\n\n  try{\n    const r = await fetch(apiBase()+'/api/payment/account', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({\n        merchant_id: S.merchantId||'demo',\n        user_id:     S.userId||'demo',\n        method:      'kripto',\n        amount:      S.amt,\n        currency:    'TRY',\n        ...kycBody()\n      })\n    });\n    const d = await r.json();\n    if(!r.ok){\n      if(d.detail === 'NO_AVAILABLE_ACCOUNT'){\n        box.innerHTML = `<div style=\"text-align:center;padding:20px\">\n          <div style=\"font-size:13px;color:#dc2626;margin-bottom:14px\">❌ Şu anda uygun hesap bulunamadı.<br>Lütfen daha düşük bir tutar deneyin veya sonra tekrar gelin.</div>\n          <button onclick=\"showPage('dep-amount')\" style=\"background:#f3f4f6;color:#374151;border:1px solid #e5e7eb;border-radius:8px;padding:8px 20px;font-size:13px;cursor:pointer\">← Tutarı Değiştir</button>\n        </div>`;\n        return;\n      }\n      throw new Error(d.detail||'Hesap alınamadı');\n    }\n\n    S._kriptoTransactionId = d.transaction_id;\n    S._kriptoData = d;\n\n    const addr          = d.deposit_address || '';\n    const cryptoAmounts = d.crypto_amounts  || {};\n    const coins         = Object.keys(cryptoAmounts);\n\n    if(!addr)         throw new Error('Adres bilgisi boş');\n    if(!coins.length) throw new Error('Kripto seçenekleri boş');\n\n    _renderKriptoInfo(addr, cryptoAmounts, d.expires_at);\n    document.getElementById('kripto-actions').style.display = 'block';\n\n  }catch(e){\n    console.error('startKripto:', e);\n    box.innerHTML = '<div style=\"color:#dc2626;font-size:13px;text-align:center;padding:24px\">⚠️ ' + (e.message||'Hesap bilgisi alınamadı') + '<br><small style=\"color:#9ca3af\">Tekrar deneyin.</small></div>';\n  } finally {\n    _kriptoLoading = false;\n  }\n}\n\nfunction _renderKriptoInfo(addr, cryptoAmounts, expiresAt){\n  const box = document.getElementById('kripto-info-box');\n\n  // Coin satırları — tümü alt alta\n  var coinRows = Object.keys(cryptoAmounts).map(function(coin){\n    var amount = cryptoAmounts[coin];\n    var isSelected = S._kriptoCoin === coin;\n    return '<div id=\"coin-row-'+coin+'\" onclick=\"selectCoin(\\''+coin+'\\')\" style=\"'\n      + 'display:flex;align-items:center;justify-content:space-between;'\n      + 'padding:12px 14px;border-radius:10px;cursor:pointer;transition:all .15s;margin-bottom:6px;'\n      + (isSelected\n          ? 'background:#eff6ff;border:2px solid #2563eb;'\n          : 'background:#f9fafb;border:2px solid transparent;')\n      + '\">'\n      + '<div style=\"display:flex;align-items:center;gap:10px\">'\n        + '<div style=\"width:36px;height:36px;border-radius:50%;background:'+(isSelected?'#2563eb':'#e5e7eb')+';display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:'+(isSelected?'#fff':'#6b7280')+'\">'+coin+'</div>'\n        + '<div>'\n          + '<div style=\"font-size:13px;font-weight:600;color:#111\">'+coin+'</div>'\n          + '<div style=\"font-size:11px;color:#6b7280\">'+amount+' '+coin+'</div>'\n        + '</div>'\n      + '</div>'\n      + '<div style=\"font-size:12px;font-weight:600;color:'+(isSelected?'#2563eb':'#9ca3af')+'\">'+(isSelected?'✓ Seçildi':'Seç')+'</div>'\n    + '</div>';\n  }).join('');\n\n  var addrShort = addr.length > 20 ? addr.slice(0,10)+'...'+addr.slice(-8) : addr;\n\n  box.innerHTML = '<div style=\"display:flex;flex-direction:column;gap:0\">'\n    // Tutar\n    + '<div style=\"display:flex;justify-content:space-between;align-items:center;padding:0 2px;margin-bottom:14px\">'\n      + '<span style=\"font-size:13px;color:#6b7280\">Yatırmak istediğin tutar</span>'\n      + '<span style=\"font-size:18px;font-weight:700;color:#2563eb\">₺' + fmt(S.amt) + '</span>'\n    + '</div>'\n    // Coin listesi\n    + '<div style=\"font-size:11px;font-weight:600;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px\">Kripto seçin</div>'\n    + coinRows\n    // Uyarı\n    + '<div style=\"background:#fefce8;border-radius:8px;padding:10px 12px;font-size:12px;color:#854d0e;margin-top:8px\">&#9888; Yalnızca seçtiğiniz coin ile gönderin. Farklı coin gönderilirse kurtarılamaz.</div>'\n    // Adres\n    + '<div style=\"margin-top:12px;padding:10px 12px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px\">'\n      + '<div style=\"font-size:11px;color:#6b7280;margin-bottom:6px;text-transform:uppercase;letter-spacing:.05em\">Gönderim Adresi</div>'\n      + '<div style=\"display:flex;align-items:center;justify-content:space-between;gap:8px\">'\n        + '<span style=\"font-family:monospace;font-size:11px;font-weight:600;word-break:break-all;color:#111\">'+addr+'</span>'\n        + '<button onclick=\"navigator.clipboard.writeText(\\''+addr+'\\');this.textContent=\\'✓\\';setTimeout(()=>this.textContent=\\'Kopyala\\',2000)\" '\n          + 'style=\"flex-shrink:0;border:1px solid #e5e7eb;border-radius:6px;padding:4px 10px;font-size:11px;cursor:pointer;background:#fff;white-space:nowrap\">Kopyala</button>'\n      + '</div>'\n    + '</div>'\n    // Süre\n    + (expiresAt ? '<div style=\"display:flex;justify-content:space-between;align-items:center;margin-top:10px;padding:0 2px\">'\n        + '<span style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em\">Kalan Süre</span>'\n        + '<span id=\"kripto-countdown\" style=\"font-family:monospace;font-size:13px;font-weight:600;color:#f59e0b\">--:--</span>'\n        + '</div>' : '')\n  + '</div>';\n\n  if(expiresAt) startHavaleCountdown(expiresAt, 'kripto-countdown');\n}\n\nfunction selectCoin(coin){\n  if(!S._kriptoData) return;\n  S._kriptoCoin = coin;\n  // Confirm buton yazısını güncelle\n  document.getElementById('kripto-confirm-label').textContent = 'Gönderdim (' + coin + ')';\n  // Coin satırlarını yeniden render et (sadece seçim vurgusu)\n  _renderKriptoInfo(\n    S._kriptoData.deposit_address,\n    S._kriptoData.crypto_amounts,\n    S._kriptoData.expires_at\n  );\n}\n\nasync function confirmKripto(){\n  if(!S._kriptoTransactionId){ document.getElementById('kripto-err').textContent='İşlem başlatılmadı.'; return; }\n  if(!S._kriptoCoin){ document.getElementById('kripto-err').textContent='Coin seçilmedi.'; return; }\n  try{\n    await fetch(apiBase()+'/api/payment/confirm', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({transaction_id: S._kriptoTransactionId, currency: S._kriptoCoin})\n    });\n  }catch(e){}\n  showPage('waiting');\n  notifySuccess(S._kriptoTransactionId);\n}\n\n// Adım 1: Yöntem seç → tutar sayfasına geç\nfunction pickMethod(m){\n  S.method = m;\n  selectedAmt = 0;\n  document.querySelectorAll('.method-opt').forEach(e=>e.classList.remove('sel'));\n  const el = document.getElementById('m-'+m);\n  if(el) el.classList.add('sel');\n  // Tutar sayfası başlığını güncelle\n  const labels = {havale:'Havale / EFT — Tutar', kripto:'Kripto — Tutar'};\n  const subs   = {havale:'Havale yapacağınız tutarı seçin.', kripto:'Kripto ile yatırmak istediğiniz TL tutarını girin.'};\n  document.getElementById('dep-amt-title').textContent = labels[m] || 'Tutar Girin';\n  document.getElementById('dep-amt-sub').textContent   = subs[m]   || 'Tutarı seçin veya girin.';\n  document.getElementById('dep-err').textContent = '';\n  document.querySelectorAll('.amt-opt').forEach(e=>e.classList.remove('sel'));\n  document.getElementById('custom-amt').value = '';\n  showPage('dep-amount');\n}\n\n// Adım 2: Tutar → ödeme detayına geç\nfunction selAmt(v,el){selectedAmt=v;document.querySelectorAll('.amt-opt').forEach(e=>e.classList.remove('sel'));el.classList.add('sel');document.getElementById('custom-amt').value=''}\nfunction customAmt(el){selectedAmt=parseFloat(el.value)||0;document.querySelectorAll('.amt-opt').forEach(e=>e.classList.remove('sel'))}\nfunction depositNext(){\n  document.getElementById('dep-err').textContent='';\n  const a=selectedAmt||parseFloat(document.getElementById('custom-amt').value)||0;\n  if(a<50){document.getElementById('dep-err').textContent='Minimum tutar ₺50 olmalıdır.';return}\n  if(a>50000){document.getElementById('dep-err').textContent='Maksimum tutar ₺50.000 olmalıdır.';return}\n  if(!collectKyc()) return;\n  S.amt=a;\n\n  if(S.method==='havale'){\n    startHavaleManuel();\n  } else if(S.method==='kripto'){\n    startKripto();\n  }\n}\n\n/* INIT */\nrenderTxns();\n// Merchant KYC'yi URL ile geçtiyse formu gizle\nif (_kycFromUrl) { var _kb=document.getElementById('kyc-box'); if(_kb) _kb.style.display='none'; }\n// iframe modunda _urlPage'e göre sayfa — DOMContentLoaded'da zaten ayarlanıyor\nif (!_urlPage) showPage('home');\n</script>\n</body>\n</html>\n"
